INSERT OR IGNORE INTO automation_settings(key, value, updated_at) VALUES ('business_replies', '{"enabled":true,"topics":{"greeting":{"enabled":true,"text":"وعليكم السلام، أهلًا وسهلًا بيك 🌷 كيف نقدر نساعدوك؟ لو تبي سعر منتج، أرسل كوده."},"delivery":{"enabled":true,"text":"لتفاصيل التوصيل، أرسل المدينة والمنطقة ونأكدلك التوفر والتكلفة."},"payment":{"enabled":true,"text":"بخصوص الدفع، فريق الصفحة يقدر يأكدلك الطرق المتاحة قبل تأكيد الطلب."},"location":{"enabled":true,"text":"لمعرفة الموقع وطريقة الاستلام، اكتب المدينة اللي تبي تستلم فيها وفريق الصفحة يساعدك."},"hours":{"enabled":true,"text":"أرسل استفسارك هنا، وفريق الصفحة يراجع رسالتك ويأكدلك مواعيد العمل."},"returns":{"enabled":true,"text":"متأسفين لو صار أي إشكال. أرسل كود المنتج وتفاصيل المشكلة، وفريق الصفحة يراجع طلبك ويوضحلك الخيارات المتاحة."},"order":{"enabled":true,"text":"يسعدنا طلبك 🌷 أرسل كود المنتج والكمية المطلوبة، وفريق الصفحة يكمل معاك التفاصيل."},"human":{"enabled":true,"text":"أكيد، اكتب استفسارك هنا. رسالتك ظاهرة لفريق الصفحة ويقدروا يتابعوها معاك."},"thanks":{"enabled":true,"text":"العفو، هذا واجبنا 🌷 موجودين لمساعدتك لو عندك أي استفسار ثاني."},"fallback":{"enabled":true,"text":"أهلًا بيك 🌷 نقدر نساعدك في أسعار المنتجات، التوصيل، الدفع، أو الطلب. اكتب سؤالك بوضوح، أو أرسل كود المنتج لمعرفة سعره."}}}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
UPDATE automation_settings SET value = json_set(value, '$.unknown', 'الكود مش موجود، تأكد من الكود وأرسله مرة ثانية.') WHERE key = 'product_bot' AND json_extract(value, '$.unknown') = 'عذرًا، ما لقيناش منتج بهذا الكود. تأكد من الكود المكتوب في المنشور وأرسله مرة ثانية، ونساعدوك بكل سرور 🌷';
